{
  "policy_type": "rules",
  "name": "policy_ep_60",
  "rules": [
    {
      "if": [
        {
          "feature": "vy",
          "op": "<",
          "value": -0.5
        },
        {
          "feature": "y",
          "op": ">",
          "value": 0
        }
      ],
      "then": 2
    },
    {
      "if": [
        {
          "feature": "theta",
          "op": ">",
          "value": 0.1
        },
        {
          "feature": "omega",
          "op": ">",
          "value": 0
        }
      ],
      "then": 1
    },
    {
      "if": [
        {
          "feature": "theta",
          "op": "<",
          "value": -0.1
        },
        {
          "feature": "omega",
          "op": "<",
          "value": 0
        }
      ],
      "then": 3
    },
    {
      "if": [
        {
          "feature": "vx",
          "op": ">",
          "value": 0.1
        },
        {
          "feature": "x",
          "op": "<",
          "value": 0
        },
        {
          "feature": "vy",
          "op": "<",
          "value": 0
        }
      ],
      "then": 3
    },
    {
      "if": [
        {
          "feature": "vx",
          "op": "<",
          "value": -0.1
        },
        {
          "feature": "x",
          "op": ">",
          "value": 0
        },
        {
          "feature": "vy",
          "op": "<",
          "value": 0
        }
      ],
      "then": 1
    },
    {
      "if": [
        {
          "feature": "left_leg",
          "op": "==",
          "value": 1
        },
        {
          "feature": "right_leg",
          "op": "==",
          "value": 1
        }
      ],
      "then": 0
    }
  ],
  "default_action": 0,
  "notes": "This new policy is influenced by Policy-1, which had an evaluated return of -162.19 and coverage statistics showing that most states fell into the default region (99.52%). The new policy retains the foundational rules of Policy-1 but introduces additional conditions to address the agent's behavior when vy is negative and both legs are in contact. This aims to encourage safe landing behaviors and reduce the likelihood of crashing, thus improving learning performance."
}

